query:
SELECT id, nomeDoEquipamento, codigoTag FROM equipamentos 
WHERE codigoTag LIKE '%TC01%' OR codigoTag LIKE '%TC05%' OR nomeDoEquipamento LIKE '%TC-01%' OR nomeDoEquipamento LIKE '%TC-05%'
ORDER BY nomeDoEquipamento;

